##  Usage
C#
Dart
Go
Java
JavaScript
Kotlin
PHP
Python
Ruby
Scala
Swift

```
// Initialize the client
var client = new SearchClient(new SearchConfig("ALGOLIA_APPLICATION_ID", "ALGOLIA_API_KEY"));

// Call the API
var response = await client.ReplaceSourcesAsync(
  new List<Source>

    new Source { VarSource = "theSource", Description = "theDescription" },

);

// print the response
Console.WriteLine(response);

```


```
// Initialize the client
final client =
    SearchClient(appId: 'ALGOLIA_APPLICATION_ID', apiKey: 'ALGOLIA_API_KEY');

// Call the API
final response = await client.replaceSources(
  source: [
    Source(
      source: "theSource",
      description: "theDescription",
    ),
  ],
);

// print the response
print(response);

```


```
// Initialize the client
client, err := search.NewClient("ALGOLIA_APPLICATION_ID", "ALGOLIA_API_KEY")
if err != nil {
  // The client can fail to initialize if you pass an invalid parameter.
  panic(err)


// Call the API
response, err := client.ReplaceSources(client.NewApiReplaceSourcesRequest(

  []search.Source{*search.NewEmptySource().SetSource("theSource").SetDescription("theDescription")}))
if err != nil {
  // handle the eventual error
  panic(err)



// print the response
print(response)

```


```
// Initialize the client
SearchClient client = new SearchClient("ALGOLIA_APPLICATION_ID", "ALGOLIA_API_KEY");

// Call the API
ReplaceSourceResponse response = client.replaceSources(
  Arrays.asList(new Source().setSource("theSource").setDescription("theDescription"))
);

// print the response
System.out.println(response);

```


```
