##  Import
JavaScript

```
import { LookingSimilar } from "react-instantsearch";

```

##  About this widget
Use the `<LookingSimilar>` widget to display a list of similar-looking products based on the image URLs you referenced when [setting up this Recommend model](https://www.algolia.com/doc/guides/algolia-recommend/how-to/lookingSimilar).
You can also create your own UI with [`useLookingSimilar`](https://www.algolia.com/doc/api-reference/widgets/looking-similar/react#hook).
##  Examples
JavaScript

```
import React from "react";
import { liteClient as algoliasearch } from "algoliasearch/lite";
import { InstantSearch, LookingSimilar } from "react-instantsearch";

const searchClient = algoliasearch("YourApplicationID", "YourSearchOnlyAPIKey");

function Item({ item }) {
  return JSON.stringify(item);


function App() {
  return (
InstantSearch indexName="instant_search" searchClient={searchClient}>
LookingSimilar objectIDs={["5723537"]} itemComponent={Item} />
    </InstantSearch>
  );


```

###  With a carousel layout
Display the `<LookingSimilar>` widget as a [scrollable carousel](https://www.algolia.com/doc/api-reference/widgets/looking-similar/react#param-layout-component)
JavaScript

```
import React from "react";
import { liteClient as algoliasearch } from "algoliasearch/lite";
import { InstantSearch, LookingSimilar, Carousel } from "react-instantsearch";

const searchClient = algoliasearch("YourApplicationID", "YourSearchOnlyAPIKey");

function Item({ item }) {
  return JSON.stringify(item);


function App() {
  return (
InstantSearch indexName="instant_search" searchClient={searchClient}>
LookingSimilar
        objectIDs={["5723537"]}
        itemComponent={Item}
        layoutComponent={Carousel}
      />
    </InstantSearch>
  );


```

