import { chat, chatTrigger } from 'instantsearch.js/es/widgets';
import 'instantsearch.css/components/chat.css';

const appID = "ALGOLIA_APPLICATION_ID";
const apiKey = "ALGOLIA_API_KEY";
const agentId = "AGENT_ID";

const searchClient = algoliasearch(appID, apiKey);
const search = instantsearch({ searchClient });

search.addWidgets([
  chat({
    container: '#chat',
    agentId,
    templates: {
      item(item, { html }) {
        return html`
          <div>
            <h3>${item.title}</h3>
            <p>${item.description}</p>
          </div>

      },
    },
    tools: {
      weather: {
        template: {
          layout: (_, { html }) => html`<div>Custom weather component</div>`,
        },
        onToolCall: ({ addToolResult }) =>
          addToolResult({ output: { temperature: 20 } }),
      },
    },
  }),
  chatTrigger({
    container: '#chat-trigger',
  }),
]);

search.start();

```

##  AI SDK UI integration
The Agent Studio is compatible with [AI SDK UI](https://ai-sdk.dev/docs/ai-sdk-ui/overview), a React-based UI integration for building conversational interfaces. Agent Studio supports both `ai-sdk` [v5](https://v5.ai-sdk.dev/) and [v4](https://v4.ai-sdk.dev/). AI SDK UI isn’t required to use Agent Studio, but it makes the integration process much easier by handling common tasks like UI rendering and state management. The benefits of using the AI SDK UI are:
  * Abstractions over low-level HTTP requests
  * Built-in error handling, retries, and extensibility using middleware and plugins
  * Fast setup for conversational user interfaces

It also allows for advanced use cases, such as:
  * Custom tool handling
  * UI state control

For more information, see the [AI SDK](https://ai-sdk.dev/docs/ai-sdk-ui/chatbot) documentation.
###  Installation
Command line

```
npm install ai @ai-sdk/react

```

###  Example React integration
React

```
import { useState } from 'react';
import { useChat } from '@ai-sdk/react';
import { DefaultChatTransport } from 'ai';

const App = () => {
  const [input, setInput] = useState('');

  const appID = "ALGOLIA_APPLICATION_ID";
  const apiKey = "ALGOLIA_SEARCH_API_KEY";
  const agentId = "AGENT_ID";

  const { messages, sendMessage } = useChat({
    transport: new DefaultChatTransport({
      api: `https://${appID}.algolia.net/agent-studio/1/agents/${agentId}/completions?stream=true&compatibilityMode=ai-sdk-5`,
      headers: {
        'x-algolia-application-id': appID,
        'x-algolia-api-key': apiKey,
      },
    }),
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    sendMessage({ text: input });
    setInput('');
  };

  return (
    <>
messages.map((message) => (
div key={message.id}>
message.role === 'user' ? 'User: ' : 'AI: '}
message.parts.map((part, index) =>
            part.type === 'text' ? <span key={index}>{part.text}</span> : null,

        </div>
      ))}

form onSubmit={handleSubmit}>
input value={input} onChange={(e) => setInput(e.target.value)} />
button type="submit">Submit</button>
      </form>
    </>
  );
};

```

##  Send agentic Insights events manually
If you don’t use InstantSearch Chat, use the ID of the assistant message that rendered the results. With Agent Studio, this is the `id` from the assistant message returned by the completion response. Store that assistant message, including its `id`, in your conversation state so later clicks and conversions can reuse the same `queryID`. Build the event `queryID` from the assistant message ID:

```
const queryID = `message_${assistantMessage.id}`;

```

Positions should match the item’s visible position in the assistant message, starting at `1`.
React
JavaScript

```
function AgenticResults({
  assistantMessage,
  items,
  userToken,
  agentId,
  toolCallId,
}) {
  const queryID = `message_${assistantMessage.id}`;

  React.useEffect(() => {
    if (items.length === 0) {
      return;


    aa('viewedObjectIDs', {
      userToken,
      index: 'products',
      eventName: 'items_shown',
      objectIDs: items.map((item) => item.objectID),
      queryID,
      agentId,
      toolCallId,
    });
  }, [agentId, items, queryID, toolCallId, userToken]);

  return (
ul>
items.map((item, index) => {
        const position = index + 1;

        return (
li key={item.objectID}>
button
              type="button"
              onClick={() =>
                aa('clickedObjectIDsAfterSearch', {
                  userToken,
                  index: 'products',
                  eventName: 'Agent Result Clicked',
                  objectIDs: [item.objectID],
                  positions: [position],
                  queryID,
                  agentId,
                  toolCallId,



item.name}
            </button>
          </li>
        );
      })}
    </ul>
  );


```


```
const queryID = `message_${assistantMessage.id}`;
const messageElement = document.querySelector(
  `[data-agentic-message-id="${assistantMessage.id}"]`
);

aa('viewedObjectIDs', {
  userToken,
  index: 'products',
  eventName: 'items_shown',
  objectIDs: items.map((item) => item.objectID),
  queryID,
  agentId,
  toolCallId,
});

messageElement
  ?.querySelectorAll('[data-agentic-result]')
  .forEach((resultElement, index) => {
    resultElement.addEventListener('click', () => {
      const objectID = resultElement.getAttribute('data-object-id');

      if (!objectID) {
        return;


      aa('clickedObjectIDsAfterSearch', {
        userToken,
        index: 'products',
        eventName: 'Agent Result Clicked',
        objectIDs: [objectID],
        positions: [index + 1],
        queryID,
        agentId,
        toolCallId,
      });
    });
  });

```

If the user converts later, reuse the same agentic `queryID` from the assistant message that showed the result.
JavaScript

```
aa('convertedObjectIDsAfterSearch', {
  userToken,
  index: 'products',
  eventName: 'Agent Result Converted',
  objectIDs: [item.objectID],
  queryID,
  agentId,
  toolCallId,
});

```

