###  Dynamic routes
If you want to generate pages dynamically—for example, one for each brand—you can use Next’s [`getStaticPaths`](https://nextjs.org/docs/pages/building-your-application/data-fetching/get-static-paths) API. The following example uses [dynamic routes](https://nextjs.org/docs/routing/dynamic-routes) along with `getStaticPaths` to create one page per brand.
JavaScript
TypeScript

```
// pages/brands/[brand].js
import { renderToString } from "react-dom/server";
import { liteClient as algoliasearch } from "algoliasearch/lite";
import {
  InstantSearch,
  InstantSearchSSRProvider,
  SearchBox,
  Hits,
  Configure,
  getServerState,
} from "react-instantsearch";

const searchClient = algoliasearch("undefined", "undefined");

export default function BrandPage({ brand, serverState }) {
  return (
InstantSearchSSRProvider {...serverState}>
InstantSearch searchClient={searchClient} indexName="YourIndexName">
Configure facetFilters={`brand:${brand}`} />
SearchBox />
Hits />
      </InstantSearch>
    </InstantSearchSSRProvider>
  );


export async function getStaticPaths() {
  return {
    // You can retrieve your brands from an API, a database, a file, etc.
    paths: [{ params: { brand: "Apple" } }, { params: { brand: "Samsung" } }],
    fallback: "blocking", // or `true` or `false`
  };


export async function getStaticProps({ params }) {
  if (!params) {
    return { notFound: true };


  const serverState = await getServerState(<BrandPage brand={params.brand} />, {
    renderToString,
  });

  return {
    props: {
      brand: params.brand,
      serverState,
    },
  };


```


