// pages/brands/[brand].tsx
import { renderToString } from 'react-dom/server';
import { liteClient as algoliasearch } from 'algoliasearch/lite';
import {
  InstantSearch,
  InstantSearchServerState,
  InstantSearchSSRProvider,
  SearchBox
  Hits,
  Configure,
  getServerState,
} from 'react-instantsearch';
import { GetStaticPathsResult, GetStaticPropsContext } from 'next';

const searchClient = algoliasearch(
  'undefined',
  'undefined'
);

type BrandPageProps = {
  brand?: string;
  serverState?: InstantSearchServerState;
};

export default function BrandPage({ brand, serverState }: BrandPageProps) {
  return (
InstantSearchSSRProvider {...serverState}>
InstantSearch searchClient={searchClient} indexName="YourIndexName">
Configure facetFilters={`brand:${brand}`} />
SearchBox />
Hits />
      </InstantSearch>
    </InstantSearchSSRProvider>
  );


type Params = {
  brand: string;
};

export function getStaticPaths(): GetStaticPathsResult<Params> {
  return {
    // You can retrieve your brands from an API, a database, a file, etc.
    paths: [{ params: { brand: 'Apple' } }, { params: { brand: 'Samsung' } }],
    fallback: 'blocking', // or `true` or `false`
  };


export async function getStaticProps({
  params,
}: GetStaticPropsContext<Params>) {
  if (!params) {
    return { notFound: true };


  const serverState = await getServerState(
BrandPage brand={params.brand} />,
renderToString }
  );

  return {
    props: {
      brand: params.brand,
      serverState,
    },
  };


```

If you have a reasonable amount of paths to generate and this number doesn’t change much, you can generate them all at build time. In this case, you can set `fallback: false`, which will serve a 404 page to users who try to visit a path that doesn’t exist (for example, a brand that isn’t in your dataset). If there are many categories and generating them all significantly slows down your build, you can pre-render only a subset of them (for example, the most popular ones) and generate the rest on the fly. With `fallback: true`, whenever a user visits a path that doesn’t exist, your `getStaticProps` code runs on the server and the page is generated once for all subsequent users. Users see a loading screen that you can implement with [`router.isFallback`](https://nextjs.org/docs/pages/api-reference/functions/get-static-paths#fallback-pages) until the page is ready. With `fallback: 'blocking'`, the scenario is the same as with `fallback: true` but there’s no loading screen. The server only returns the HTML once the page is generated.
##  With Remix
[Remix](https://remix.run/) is a full-stack web framework that encourages usage of runtime servers, notably for server-side rendering. Server-side rendering a page in Remix is split in two parts:
  * A [loader](https://remix.run/docs/en/v1/api/conventions#loader) that returns data from the server,
  * A React component for the page that receives this data.

In the page, you need to wrap the search experience with the [`InstantSearchSSRProvider`](https://www.algolia.com/doc/api-reference/widgets/ssr-provider/react) component. This provider receives the server state and forwards it to the entire InstantSearch app. In Remix’ loader, you can use [`getServerState`](https://www.algolia.com/doc/api-reference/widgets/server-state/react) to return the server state. To support routing, forward the server’s request URL to the [`history`](https://www.algolia.com/doc/api-reference/widgets/history-router/js) router.
JavaScript
TypeScript

```
// index.js
import { renderToString } from "react-dom/server";
import { liteClient as algoliasearch } from "algoliasearch/lite";
import {
  InstantSearch,
  InstantSearchSSRProvider,
  getServerState,
} from "react-instantsearch";
import { history } from "instantsearch.js/cjs/lib/routers/index.js";

import { json } from "@remix-run/node";
import { useLoaderData } from "@remix-run/react";

const searchClient = algoliasearch("undefined", "undefined");

export async function loader({ request }) {
  const serverUrl = request.url;
  const serverState = await getServerState(<Search serverUrl={serverUrl} />, {
    renderToString,
  });

  return json({
    serverState,
    serverUrl,
  });


function Search({ serverState, serverUrl }) {
  return (
InstantSearchSSRProvider {...serverState}>
InstantSearch
        searchClient={searchClient}
        indexName="YourIndexName"
        routing={{
          router: history({
            getLocation() {
              if (typeof window === "undefined") {
                return new URL(serverUrl);


              return window.location;

          }),


/* Widgets */}
      </InstantSearch>
    </InstantSearchSSRProvider>
  );


export default function HomePage() {
  const { serverState, serverUrl } = useLoaderData();

  return <Search serverState={serverState} serverUrl={serverUrl} />;


```


