      },
    };

    if (typeof allWidgetConfiguration["toggleRefinement"] === "undefined") {
      allWidgetConfiguration["toggleRefinement"] = [widgetConfig];
else {
      allWidgetConfiguration["toggleRefinement"].push(widgetConfig);


    return allWidgetConfiguration;
  },
);

```

All default widgets can be found in `allWidgetConfiguration` object and can be removed or modified in this method. However, some widgets, like hits, can not be added multiple times. In that case, you should add the widget manually in `beforeInstantsearchStart`:
Version 3.15.0 and up
InstantSearch.js 4.x (pre 3.15.0)
InstantSearch.js 2.x

```
define(["algoliaCommon", "algoliaInstantSearchLib"], function (
  algolia,
  instantsearch,
) {
  algolia.registerHook("beforeInstantsearchStart", function (search) {
    search.addWidgets([
      instantsearch.widgets.hits({
        container: "#custom-second-hits",
      }),
    ]);
    return search;
  });
});

```


```
algolia.registerHook(
  "beforeInstantsearchStart",
  function (search, algoliaBundle) {
    search.addWidgets([
      algoliaBundle.instantsearch.widgets.hits({
        container: "#custom-second-hits",
      }),
    ]);
    return search;
  },
);

```


```
algolia.registerHook(
  "beforeInstantsearchStart",
  function (search, algoliaBundle) {
    search.addWidget(
      algoliaBundle.instantsearch.widgets.hits({
        container: "#custom-second-hits",
      }),
    );
    return search;
  },
);

```

The following code demonstrates how you might modify the `color` facet in any number of ways using the `beforeFacetInitialization(builders)` hook:
JavaScript

```
define(['algoliaCommon','algoliaInstantSearchLib'], function (algolia, instantsearch) { 
  algolia.registerHook(
      "beforeFacetInitialization",
      function (builders) {
          console.log("InstantSearch facet builders:", builders);

          // Add a new builder function for the `color` attribute
          builders.color = (facet) => {
              const options = {
                  attribute: facet.attribute,

                  container: algolia.createISWidgetContainer(facet.attribute),

                  // Override the default sort which sorts by `count:desc`
                  sortBy: ['name:asc'],

                  // Inject additional data into your facet items
                  transformItems(items, {results: {hits}}) {
                      return items.map(item => ({
                          ...item,
                          // For instance you might add a swatch URL - this could be extracted from the hits data which has been augmented to include this data through a customization
                          swatchUrl: 'https://placehold.co/16x16' //getSwatchUrlFromHits(hits) and so on.
                      }));


                  templates: {
                      item(item, { html }) {
                          const { url, label, count, isRefined, swatchUrl } = item;
                          // Include the swatch in the rendered item 
                          return html`
                              <a href="${url}" style="${isRefined ? 'font-weight: bold' : ''}">
                                <span><img src="${swatchUrl}"/> ${label} (${count})</span>
                              </a>




                  // The Magento integration supports the inclusion of a `panelOptions` object to define how the wrapping panel might look or behave
                  panelOptions: {
                      templates: {
                          // Customizing the header
                          header: `<div class="name">CUSTOM FACET: ${facet.label}</div>`


                      // Control whether or not the panel appears 
                      hidden(options) {
                          return !options.results;




              // Return a tuple of your desired widget type and the options to be passed to that widget 
              return ['refinementList', options];
          };

          return builders;

  );
);

```

In the preceding example, a custom builder function is used to return the configuration for a [`refinementList` widget](https://www.algolia.com/doc/api-reference/widgets/refinement-list/js).
##  Insights events
You can add new events for [click and conversion analytics](https://www.algolia.com/doc/integration/magento-2/how-it-works/events) and [Personalization](https://www.algolia.com/doc/integration/magento-2/how-it-works/personalization) by registering this custom hook:
  * `afterInsightsBindEvents(algoliaInsights)`
    * can be used to add new events
    * `algoliaInsights` gives you access to methods for tracking:
      * `trackClick(eventData)`
      * `trackView(eventData)`
      * `trackConversion(eventData)`
    * to format `eventData` for insights you can use:
      * `buildEventData(eventName, objectID, indexName, position = null, queryID = null)`
      * Click and Conversion Analytics requires the optional parameters for `position` and `queryID`

Example of a custom click event for personalization:
JavaScript

```
algolia.registerHook("afterInsightsBindEvents", function (algoliaInsights) {
  var selectors = document.querySelectorAll(".class-selector");
  selectors.forEach(function (e) {
    e.addEventListener("click", function (event) {
      // selector in this example has an data-objectid attribute
      // with the objectID as the value
      var objectId = this.dataset.objectid;

      // use the buildEventData function to format event data
      var eventData = algoliaInsights.buildEventData(
        "Clicked Event Name", // eventName
        objectId, // objectID
        algoliaConfig.indexName + "_products", // indexName
      );

      algoliaInsights.trackClick(eventData);
    });
  });
});

```

##  Example usages
You can use this section as inspiration for your customization.
###  Add category sorting in the Autocomplete menu
This examples creates a new section that displays categories with the product results. To learn more about templating, see [Create a custom extension](https://www.algolia.com/doc/integration/magento-2/guides/create-a-custom-extension). To get the categories that are returned by a product search, you need to create a new section that queries the products index. When you define the source of this section, pass the [`facets`](https://www.algolia.com/doc/api-reference/api-parameters/facets) parameter that returns the categories attribute which the extension indexes as: `categories.level0` or `categories.level2`. The search returns product results as hits, so you need to render the facets instead of products. You can render the facets in the template suggestions function. Make sure that your template variables match those returned by the facets to render them in autocomplete.
JavaScript

```
algolia.registerHook(
  "beforeAutocompleteSources",
  function (sources, algoliaClient) {
    let source = {
      hitsPerPage: 2,
      label: "Category w/ Products ",
      name: "products",
      options: {
        analyticsTags: "autocomplete",
        clickAnalytics: true,
        distinct: true,
        facets: ["categories.level0, categories.level2"],
        maxValuesPerFacet: 3,
      },
      paramName: algoliaClient.initIndex(
        algoliaConfig.indexName + "_" + "products",
      ),
      templates: {
        noResults({ html }) {
          return "No Results";
        },
        header({ html, items }) {
          return "Category w/ Products";
        },
        item({ item, components, html }) {
          // Their Html will go here
        },
        footer({ html, items }) {
          return "";
        },
      },
    };
    sources.push(source);
    return sources;
  },
);

```

###  Add filters to your autocomplete search
To add a new , modify the section’s search parameters to include the new filter condition. To do this, you need to recreate the source with the updated options. The example below adds a new [`numericFilters`](https://www.algolia.com/doc/api-reference/api-parameters/numericFilters) to the search parameters, `in_stock=1`. To recreate the source value, you need to recreate the options passed into the product source as defined in [`common.js`](https://github.com/algolia/algoliasearch-magento-2/blob/master/view/frontend/web/js/internals/common.js). The `numericFilters` returns an array of conditions that includes the new condition.
JavaScript

```
algolia.registerHook(
  "beforeAutocompleteProductSourceOptions",
  function (options) {
    ((options.analyticsTags = "autocomplete"),
options.clickAnalytics = true),
options.facets = ["categories.level0"]),
options.numericFilters = ["visibility_search=1", "in_stock=1"]));
    return options;
  },
);

```

###  Add custom rules context to InstantSearch
If you have to add new contexts for some of your custom rules, use the specified frontend hook for your InstantSearch version. You should add your new context to the preconfigured contexts:
InstantSearch.js 4
InstantSearch.js 2

```
algolia.registerHook(
  "beforeWidgetInitialization",
  function (allWidgetConfiguration) {
    // Adding a custom Query Rule context
    var newQueryRuleContext = "new-custom-query-rule-context";
    allWidgetConfiguration.configure.ruleContexts.push(newQueryRuleContext);

    return allWidgetConfiguration;
  },
);

```


```
algolia.registerHook(
  "beforeInstantsearchInit",
  function (instantsearchOptions) {
    // Adding a custom Query Rule context
    var newQueryRuleContext = "new-custom-query-rule-context";
    instantsearchOptions.searchParameters.ruleContexts.push(
      newQueryRuleContext,
    );

    return instantsearchOptions;
  },
);

```

###  Sort facet values with InstantSearch
By default, facet values displayed for a search are sorted by the number of matching results. The following example shows, how to sort the size facet values based on the `size` values. To do this, you need to hook into the event `beforeWidgetInitialization` to modify the facet for size. To sort the values in the `refinementList` based on size, add the [`sortBy`](https://www.algolia.com/doc/api-reference/widgets/sort-by/js) function to the `refinementList`. This function lets you match values against each other and sort each value. To determine the order, use the `orderedSizes` array variable defined in the code below. This can be pulled from any source, like Magento or from another index if needed.
JavaScript

```
algolia.registerHook(
  "beforeWidgetInitialization",
  function (allWidgetConfiguration) {
    var orderedSizes = ["XXS", "XS", "S", "M", "L", "XL", "XXL"];

    for (var i = 0; i < allWidgetConfiguration.refinementList.length; i++) {
      if (allWidgetConfiguration.refinementList[i].attribute == "size") {
        allWidgetConfiguration.refinementList[i].sortBy = function (a, b) {
          return orderedSizes.indexOf(a.name) - orderedSizes.indexOf(b.name);
        };



    return allWidgetConfiguration;
  },
);

```

