```
const renderToggleRefinement = (renderOptions, isFirstRender) => {
  const { value } = renderOptions;

  document.querySelector("#toggle-refinement").innerHTML = `
    <label>
      <input type="checkbox" ${value.isRefined ? "checked" : ""} />
      Free shipping (${value.count})
    </label>

};

```

