import { h, render } from "preact";

import "@algolia/autocomplete-theme-classic";

autocomplete({
  container: "#autocomplete",
  openOnFocus: true,
  plugins: [],
  render(params, root) {
    render(
div className="aa-PanelLayout aa-Panel--scrollable">
div className="aa-PanelSections">
div className="aa-PanelSection--left"></div>
div className="aa-PanelSection--right"></div>
        </div>
      </div>,
      root,
    );
  },
});

```

##  Add recent searches and Query Suggestions
Add the [recent searches](https://www.algolia.com/doc/ui-libraries/autocomplete/api-reference/autocomplete-plugin-recent-searches) (with a limit of two recent searches) and [Query Suggestions](https://www.algolia.com/doc/ui-libraries/autocomplete/api-reference/autocomplete-plugin-query-suggestions) plugin (limiting the number of suggestions to seven) to the left column. This gives a total of nine items in the right column. Then, retrieve the recent searches and query suggestions plugins sources in the [`render`](https://www.algolia.com/doc/ui-libraries/autocomplete/api-reference/autocomplete-js/autocomplete#param-render) function using `elements` and add it to the left column.
JavaScript
JSX

```
// ...
import { createLocalStorageRecentSearchesPlugin } from "@algolia/autocomplete-plugin-recent-searches";
import { createQuerySuggestionsPlugin } from "@algolia/autocomplete-plugin-query-suggestions";
import { liteClient as algoliasearch } from "algoliasearch/lite";

import "@algolia/autocomplete-theme-classic";

// You can use the example application credentials in case you don't have your own yet.
// const appId = 'latency';
// const apiKey = '6be0576ff61c053d5f9a3225e2a90f76';
const searchClient = algoliasearch("YourApplicationID", "YourSearchOnlyAPIKey");

const recentSearchesPlugin = createLocalStorageRecentSearchesPlugin({
  key: "multi-column-layout-example",
  limit: 2,
});

const querySuggestionsPlugin = createQuerySuggestionsPlugin({
  searchClient,
  indexName: "autocomplete_demo_products_query_suggestions",
  getSearchParams() {
    return {
      ...recentSearchesPlugin.data.getAlgoliaSearchParams(),
      hitsPerPage: 7,
    };
  },
});

autocomplete({
  container: "#autocomplete",
  openOnFocus: true,
  plugins: [recentSearchesPlugin, querySuggestionsPlugin],
  render({ elements, render, html }, root) {
    const { recentSearchesPlugin, querySuggestionsPlugin } = elements;

    render(
      html`<div class="aa-PanelLayout aa-Panel--scrollable">
        <div class="aa-PanelSections">
          <div class="aa-PanelSection--left">
            ${recentSearchesPlugin} ${querySuggestionsPlugin}
          </div>
          <div class="aa-PanelSection--right"></div>
        </div>
      </div>`,
      root,
    );
  },
});

```


