export default function App() {
  return (
SafeAreaView style={styles.safe}>
StatusBar style="light" />
View style={styles.container}>
InstantSearch searchClient={searchClient} indexName="INDEX_NAME">
/* ... */}
        </InstantSearch>
      </View>
    </SafeAreaView>
  );


const styles = StyleSheet.create({
  safe: {
    flex: 1,
    backgroundColor: "#252b33",
  },
  container: {
    flex: 1,
    backgroundColor: "#ffffff",
    flexDirection: "column",
  },
});

```

Replace `INDEX_NAME` with the name of your . Add styles using the [`StyleSheet`](https://reactnative.dev/docs/stylesheet) API from React Native.
##  Add a search box
The main UI component of a search experience is a search box. It’s often how users discover content in your app. React InstantSearch provides a [`useSearchBox`](https://www.algolia.com/doc/api-reference/widgets/search-box/react#hook) Hook to display an Algolia search box. Use it with the [`TextInput`](https://reactnative.dev/docs/textinput) React Native component. Then, add the custom `SearchBox` component to your app.
SearchBox.js
App.js

```
import React, { useRef, useState } from "react";
import { StyleSheet, View, TextInput } from "react-native";
import { useSearchBox } from "react-instantsearch-core";

export function SearchBox(props) {
  const { query, refine } = useSearchBox(props);
  const [inputValue, setInputValue] = useState(query);
  const inputRef = useRef(null);

  function setQuery(newQuery) {
    setInputValue(newQuery);
    refine(newQuery);


  // Track when the InstantSearch query changes to synchronize it with
  // the React state.
  // Bypass the state update if the input is focused to avoid concurrent
  // updates when typing.
  if (query !== inputValue && !inputRef.current?.isFocused()) {
    setInputValue(query);


  return (
View style={styles.container}>
TextInput
        ref={inputRef}
        style={styles.input}
        value={inputValue}
        onChangeText={setQuery}
        clearButtonMode="while-editing"
        autoCapitalize="none"
        autoCorrect={false}
        spellCheck={false}
        autoComplete="off"
      />
    </View>
  );


const styles = StyleSheet.create({
  container: {
    backgroundColor: "#252b33",
    padding: 18,
  },
  input: {
    height: 48,
    padding: 12,
    fontSize: 16,
    backgroundColor: "#fff",
    borderRadius: 4,
    borderWidth: 1,
    borderColor: "#ddd",
  },
});

