##  Highlight matches
Algolia supports highlighting and returns the highlighted parts of a result in the response. Build a custom `Highlight` component to highlight matches in each attribute. The `instantsearch.js` library provides the necessary utilities to parse the highlighted parts from the Algolia response. React InstantSearch uses InstantSearch.js behind the scenes, so you don’t need to include it as a separate dependency. Use the [`Text`](https://reactnative.dev/docs/text) component from React Native to represent each highlighted and non-highlighted part. Then, use the custom `Highlight` component in your custom `Hit` component.
Highlight.js
App.js

```
import React, { Fragment } from "react";
import { StyleSheet, Text } from "react-native";
import {
  getHighlightedParts,
  getPropertyByPath,
} from "instantsearch.js/es/lib/utils";

function HighlightPart({ children, isHighlighted }) {
  return (
Text style={isHighlighted ? styles.highlighted : styles.nonHighlighted}>
children}
    </Text>
  );


export function Highlight({ hit, attribute, separator = ", " }) {
  const { value: attributeValue = "" } =
    getPropertyByPath(hit._highlightResult, attribute) || {};
  const parts = getHighlightedParts(attributeValue);

  return (
    <>
parts.map((part, partIndex) => {
        if (Array.isArray(part)) {
          const isLastPart = partIndex === parts.length - 1;

          return (
Fragment key={partIndex}>
part.map((subPart, subPartIndex) => (
HighlightPart
                  key={subPartIndex}
                  isHighlighted={subPart.isHighlighted}

subPart.value}
                </HighlightPart>
              ))}

!isLastPart && separator}
            </Fragment>
          );


        return (
HighlightPart key={partIndex} isHighlighted={part.isHighlighted}>
part.value}
          </HighlightPart>
        );
      })}
    </>
  );


const styles = StyleSheet.create({
  highlighted: {
    fontWeight: "bold",
    backgroundColor: "#f5df4d",
    color: "#6f6106",
  },
  nonHighlighted: {
    fontWeight: "normal",
    backgroundColor: "transparent",
    color: "black",
  },
});

```


