##  Add a filter
A search box is a great way to refine a search experience, but sometimes users need to narrow down the results to find what they’re looking for in a specific category. Use the [`useRefinementList`](https://www.algolia.com/doc/api-reference/widgets/refinement-list/react#hook) Hook to items based on attributes such as brand, size, or color. Mobile devices have limited screen real estate. Instead of displaying filters near the list of hits as you would on a desktop website, mobile apps commonly set filters inside a modal. With React Native, use the [`Modal`](https://reactnative.dev/docs/modal) component.
Filters.js
App.js

```
import React from "react";
import {
  Button,
  StyleSheet,
  SafeAreaView,
  Modal,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import {
  useClearRefinements,
  useCurrentRefinements,
  useRefinementList,
} from "react-instantsearch-core";

export function Filters({ isModalOpen, onToggleModal, onChange }) {
  const { items, refine } = useRefinementList({ attribute: "brand" });
  const { canRefine: canClear, refine: clear } = useClearRefinements();
  const { items: currentRefinements } = useCurrentRefinements();
  const totalRefinements = currentRefinements.reduce(
    (acc, { refinements }) => acc + refinements.length,

  );

  return (
    <>
TouchableOpacity style={styles.filtersButton} onPress={onToggleModal}>
Text style={styles.filtersButtonText}>Filters</Text>
totalRefinements > 0 && (
View style={styles.itemCount}>
Text style={styles.itemCountText}>{totalRefinements}</Text>
          </View>

      </TouchableOpacity>

Modal animationType="slide" visible={isModalOpen}>
SafeAreaView>
View style={styles.container}>
View style={styles.title}>
Text style={styles.titleText}>Brand</Text>
            </View>
View style={styles.list}>
items.map((item) => {
                return (
TouchableOpacity
                    key={item.value}
                    style={styles.item}
                    onPress={() => {
                      refine(item.value);
                      onChange();


Text
                      style={{
                        ...styles.labelText,
                        fontWeight: item.isRefined ? "800" : "400",


item.label}
                    </Text>
View style={styles.itemCount}>
Text style={styles.itemCountText}>{item.count}</Text>
                    </View>
                  </TouchableOpacity>

              })}
            </View>
          </View>
View style={styles.filterListButtonContainer}>
View style={styles.filterListButton}>
Button
                title="Clear all"
                color="#252b33"
                disabled={!canClear}
                onPress={() => {
                  clear();
                  onChange();
                  onToggleModal();


            </View>
View style={styles.filterListButton}>
Button
                onPress={onToggleModal}
                title="See results"
                color="#252b33"

            </View>
          </View>
        </SafeAreaView>
      </Modal>
    </>
  );


const styles = StyleSheet.create({
  container: {
    padding: 18,
    backgroundColor: "#ffffff",
  },
  title: {
    alignItems: "center",
  },
  titleText: {
    fontSize: 32,
  },
  list: {
    marginTop: 32,
  },
  item: {
    paddingVertical: 12,
    flexDirection: "row",
    justifyContent: "space-between",
    borderBottomWidth: 1,
    borderColor: "#ddd",
    alignItems: "center",
  },
  itemCount: {
    backgroundColor: "#252b33",
    borderRadius: 24,
    paddingVertical: 4,
    paddingHorizontal: 8,
    marginLeft: 4,
  },
  itemCountText: {
    color: "#ffffff",
    fontWeight: "800",
  },
  labelText: {
    fontSize: 16,
  },
  filterListButtonContainer: {
    flexDirection: "row",
  },
  filterListButton: {
    flex: 1,
    alignItems: "center",
    marginTop: 18,
  },
  filtersButton: {
    paddingVertical: 18,
    flexDirection: "row",
    justifyContent: "center",
    alignItems: "center",
  },
  filtersButtonText: {
    fontSize: 18,
    textAlign: "center",
