  "id": "your-conversation-id",
  "messages": [

      "role": "user",
      "content": "What is Algolia?",
      "id": "msg-123",
      "createdAt": "2025-01-01T12:00:00.000Z",
      "parts": [

          "type": "text",
          "text": "What is Algolia?"



  ],
  "searchParameters": {
    "facetFilters": ["language:en", "version:latest"]



```

