map(
item) => `
            <li>

                href="#"
                data-value="${item.value}"
                style="font-weight: ${item.isRefined ? "bold" : ""}"

                ${item.label} (${item.count})
              </a>
            </li>`,

join("")}
    </ul>


  [...container.querySelectorAll("a")].forEach((element) => {
    element.addEventListener("click", (event) => {
      event.preventDefault();
      refine(event.currentTarget.dataset.value);
    });
  });
};

```

sendEvent
(eventType, facetValue) => void
The function to send `click` events. The `click` event is automatically sent when `refine` is called. To learn more, see the [`insights`](https://www.algolia.com/doc/api-reference/widgets/insights/js) middleware.
  * `eventType: 'click'`
  * `facetValue: string`


