const response = await client.searchSingleIndex({
  indexName: "INDEX_NAME",
  searchParams: {
    query: "YourSearchQuery",
    userToken: "user-1",
    clickAnalytics: true,
  },
});
const { hits, queryID } = response;
console.log(hits, queryID);

```


