li key={item.label} data-insights-filter={`${brand}:${item.value}`}>

              href="#"
              style={{ fontWeight: item.isRefined ? "bold" : "" }}
              onClick={(event) => {
                event.preventDefault();
                refine(item.value);


item.label} ({item.count})
