<script lang="jsx">
/* ... */
export default {
  /* ... */
  mounted() {
    /* ... */
    function setInstantSearchUiState({
      query,
      category,
      resetCategory = false,
    }) {
      let hierarchicalMenu;
      if (resetCategory) {
        hierarchicalMenu = {
          hierarchicalMenu: { [INSTANT_SEARCH_HIERARCHICAL_ATTRIBUTE]: [] },
