          hierarchicalMenu: {
INSTANT_SEARCH_HIERARCHICAL_ATTRIBUTE]: [category],
          },
        };


      instantSearchInstance.setUiState((uiState) => ({
        ...uiState,
INSTANT_SEARCH_INDEX_NAME]: {
          ...uiState[INSTANT_SEARCH_INDEX_NAME],
          page: 1,
          query,
          ...hierarchicalMenu,
        },
      }));

  },

</script>

