##  Add contextual Query Suggestions
For an even richer Autocomplete experience, you can pick up the currently active InstantSearch category and provide suggestions for both this specific category and others. This pattern lets you reduce the search scope to the current category, like an actual department store, or broaden the suggestions to get out of the current category. First, make sure to set your category attribute as a facet in your Query Suggestions index. In this demo, the attribute to facet is `instant_search.facets.exact_matches.hierarchicalCategories.lvl0.value`.
Autocomplete.vue (Vue 3)
Autocomplete.vue (Vue 2)

```
<script lang="jsx">
/* ... */
export default {
  /* ... */
  mounted() {
    /* ... */
    // Get the current category from InstantSearch
    function getInstantSearchCurrentCategory() {
      const indexRenderState =
        instantSearchInstance.renderState[INSTANT_SEARCH_INDEX_NAME];
      const refinedCategory = indexRenderState?.hierarchicalMenu?.[
        INSTANT_SEARCH_HIERARCHICAL_ATTRIBUTE
      ]?.items?.find(({ isRefined }) => isRefined);

      return refinedCategory?.value;


    /* ... */

    // Query Suggestions plugin for the current category
    const querySuggestionPluginInCategory = createQuerySuggestionsPlugin({
      searchClient,
      indexName: INSTANT_SEARCH_QUERY_SUGGESTIONS,
      getSearchParams() {
        const currentCategory = getInstantSearchCurrentCategory();
        return recentSearchesPlugin.data.getAlgoliaSearchParams({
          hitsPerPage: 3,
          facetFilters: [
${INSTANT_SEARCH_INDEX_NAME}.facets.exact_matches.${INSTANT_SEARCH_HIERARCHICAL_ATTRIBUTE}.value:${currentCategory}`,
          ],
        });
      },
      transformSource({ source }) {
        const currentCategory = getInstantSearchCurrentCategory();
        return {
          ...source,
          sourceId: "querySuggestionsPluginInCategory",
          getItems(params) {
            if (!currentCategory) {
              return [];


            return source.getItems(params);
          },
          templates: {
            ...source.templates,
            header({ items }) {
              if (!items.length) {
                return null;


              return (
Fragment>
span className="aa-SourceHeaderTitle">
                    In {currentCategory}
                  </span>
span className="aa-SourceHeaderLine"></span>
                </Fragment>


          },
        };
      },
    });

    // Query Suggestions plugin for the other categories
    const querySuggestionsPlugin = createQuerySuggestionsPlugin({
      /* ... */
      getSearchParams() {
        const currentCategory = getInstantSearchCurrentCategory();
        if (!currentCategory) {
          return recentSearchesPlugin.data.getAlgoliaSearchParams({
            hitsPerPage: 6,
          });


        return recentSearchesPlugin.data.getAlgoliaSearchParams({
          hitsPerPage: 3,
          facetFilters: [
${INSTANT_SEARCH_INDEX_NAME}.facets.exact_matches.${INSTANT_SEARCH_HIERARCHICAL_ATTRIBUTE}.value:-${currentCategory}`,
          ],
        });
      },
      transformSource({ source }) {
        const currentCategory = getInstantSearchCurrentCategory();

        return {
          ...source,
          /* ... */
          templates: {
            ...source.templates,
            header({ items }) {
              if (!currentCategory || !items.length) {
                return null;


              return (
Fragment>
span className="aa-SourceHeaderTitle">
                    In other categories
                  </span>
span className="aa-SourceHeaderLine"></span>
                </Fragment>


          },
        };
      },
    });
  },

</script>

