  return useConnector(connectVoiceSearch, props);


export function VoiceSearch(props) {
  const {
    isBrowserSupported,
    isListening,
    toggleListening,
    voiceListeningState,
  } = useVoiceSearch(props);

  return <>{/* Your JSX */}</>;


