###  Example
JavaScript
TypeScript

```
import React from "react";
import { useHierarchicalMenu } from "react-instantsearch";

function CustomHierarchicalMenu(props) {
  const {
    items,
    refine,
    canToggleShowMore,
    toggleShowMore,
    isShowingMore,
    createURL,
  } = useHierarchicalMenu(props);

  return (
    <>
HierarchicalList
        items={items}
        onNavigate={refine}
        createURL={createURL}
      />
props.showMore && (
button disabled={!canToggleShowMore} onClick={toggleShowMore}>
isShowingMore ? "Show less" : "Show more"}
        </button>

    </>
  );


function HierarchicalList({ items, createURL, onNavigate }) {
  if (items.length === 0) {
    return null;


  return (
ul>
items.map((item) => (
li key={item.value}>

            href={createURL(item.value)}
            onClick={(event) => {
              if (isModifierClick(event)) {
                return;

              event.preventDefault();

              onNavigate(item.value);

            style={{ fontWeight: item.isRefined ? "bold" : "normal" }}

span>{item.label}</span>
span>{item.count}</span>
          </a>
item.data && (
HierarchicalList
              items={item.data}
              onNavigate={onNavigate}
              createURL={createURL}


        </li>
      ))}
    </ul>
  );


function isModifierClick(event) {
  const isMiddleClick = event.button === 1;
  return Boolean(
    isMiddleClick ||
      event.altKey ||
      event.ctrlKey ||
      event.metaKey ||
      event.shiftKey,
  );


```


```
import React from "react";
import {
  useHierarchicalMenu,
  UseHierarchicalMenuProps,
} from "react-instantsearch";

function CustomHierarchicalMenu(props: UseHierarchicalMenuProps) {
  const {
    items,
    refine,
    canToggleShowMore,
    toggleShowMore,
    isShowingMore,
    createURL,
  } = useHierarchicalMenu(props);

  return (
    <>
HierarchicalList
        items={items}
        onNavigate={refine}
        createURL={createURL}
      />
props.showMore && (
button disabled={!canToggleShowMore} onClick={toggleShowMore}>
isShowingMore ? "Show less" : "Show more"}
        </button>

    </>
  );


type HierarchicalListProps = Pick<
  ReturnType<typeof useHierarchicalMenu>,
  "items" | "createURL"
> & {
  onNavigate(value: string): void;
};

function HierarchicalList({
  items,
  createURL,
  onNavigate,
}: HierarchicalListProps) {
  if (items.length === 0) {
    return null;


  return (
ul>
items.map((item) => (
li key={item.value}>

            href={createURL(item.value)}
            onClick={(event) => {
              if (isModifierClick(event)) {
                return;

              event.preventDefault();

              onNavigate(item.value);

            style={{ fontWeight: item.isRefined ? "bold" : "normal" }}

span>{item.label}</span>
span>{item.count}</span>
          </a>
item.data && (
HierarchicalList
              items={item.data}
              onNavigate={onNavigate}
              createURL={createURL}


        </li>
      ))}
    </ul>
  );


function isModifierClick(event: React.MouseEvent) {
  const isMiddleClick = event.button === 1;
  return Boolean(
    isMiddleClick ||
      event.altKey ||
      event.ctrlKey ||
      event.metaKey ||
      event.shiftKey,
  );


```

