  const { items, refine } = useMenu(props);
  const { value: selectedValue } = items.find((item) => item.isRefined) || {
    value: "",
  };

  return (
select
      value={selectedValue}
      onChange={(event) => {
        refine((event.target as HTMLSelectElement).value);


items.map((item) => (
option value={item.value}>
item.label} ({item.count})
        </option>
      ))}
    </select>
  );


```

