```
promptSuggestions({
  container: '#prompt-suggestions',
  agentId: '8f7c4a2d-3b1e-4d5f-9a6c-e2b1f5d0c3e9',
  configurationId: 'CONFIGURATION_ID',
});

chat({
  container: '#chat',
  agentId: '8f7c4a2d-3b1e-4d5f-9a6c-e2b1f5d0c3e9',
});

```

