##  About this Hook
A React Hook that lets you use an InstantSearch connector in a React component. Use this for connecting [your own connectors](https://www.algolia.com/doc/guides/building-search-ui/widgets/create-your-own-widgets/js#build-a-custom-connector) with React InstantSearch.
##  Examples
JavaScript
TypeScript

```
import { useConnector } from "react-instantsearch";
import connectGeoSearch from "instantsearch.js/es/connectors/geo-search/connectGeoSearch";

export function useGeoSearch(props, additionalWidgetProperties) {
  return useConnector(connectGeoSearch, props, additionalWidgetProperties);


export function GeoSearch(props) {
  const { items, refine } = useGeoSearch(props, {
    $$widgetType: "my-organization.geoSearch",
  });

  return <>{/* Your JSX */}</>;


```


```
import { useConnector, AdditionalWidgetProperties } from "react-instantsearch";
import connectGeoSearch, {
  GeoSearchConnectorParams,
  GeoSearchWidgetDescription,
} from "instantsearch.js/es/connectors/geo-search/connectGeoSearch";

export type UseGeoSearchProps = GeoSearchConnectorParams;

export function useGeoSearch(
  props: UseGeoSearchProps,
  additionalWidgetProperties: AdditionalWidgetProperties,
) {
  return useConnector<GeoSearchConnectorParams, GeoSearchWidgetDescription>(
    connectGeoSearch,
    props,
    additionalWidgetProperties,
  );


export function GeoSearch(props: UseGeoSearchProps) {
  const { items, refine } = useGeoSearch(props, {
    $$widgetType: "my-organization.geoSearch",
  });

  return <>{/* Your JSX */}</>;


```

