import { useNumericMenu } from "react-instantsearch";

```

## See this widget in action
Preview this widget and its behavior.
##  About this Hook
React Hook for a list of numeric filters that are pre-configured when creating the widget. Numeric menus let users choose a single value for a specific attribute.
###  Requirements
The attribute provided to the hook is already declared as an [attribute for faceting](https://www.algolia.com/doc/guides/managing-results/refine-results/faceting/how-to/declaring-attributes-for-faceting). All values must be numbers, not strings.
##  Examples
JavaScript
TypeScript

```
import React from 'react';
import { useNumericMenu } from 'react-instantsearch';

function NumericMenu(props) {
  const { items, refine } = useNumericMenu(props);

  return (
ul>
items.map((item) => (
li key={item.value}>
label>
input
              type="radio"
              name={item.attribute}
              defaultChecked={item.isRefined}
              onChange={(event) => {
                event.preventDefault();

                refine(item.value);


span>{item.label}</span>
          </label>
        </li>
      ))}
    </ul>
  );


```


