 "ais-RatingMenu-starSymbol"
 "ais-RatingMenu-starEmptySymbol"}"

              </svg>


          <span class="${data.cssClasses.label}">& Up</span>
          <span class="${data.cssClasses.count}">${data.count}</span>
        </a>

    },
  },
});

