                <span>${item.name} &amp; Up</span>
                <span>${item.count}</span>
              </a>
            </li>`,

join("")}
    </ul>

};

```

###  Create and instantiate the custom widget
First, create your custom widgets using a rendering function. Then, instantiate them with parameters. There are two kinds of parameters you can pass:
  * **Instance parameters**. Predefined options that configure Algolia’s behavior.
  * **Custom parameters**. Parameters you define to make the widget reusable and adaptable.

Inside the `renderFunction`, both instance and custom parameters are accessible through `connector.widgetParams`.
JavaScript

```
const customRatingMenu = connectRatingMenu(renderRatingMenu);

search.addWidgets([
  customRatingMenu({
    attribute,
    // Optional parameters
    max,
  }),
]);

```

####  Instance options
attribute
string
required
The name of the attribute in the record.
JavaScript

```
customRatingMenu({
  attribute: "rating",
});

```

max
number
default:5
The maximum value for the rating.
JavaScript

```
customRatingMenu({
  // ...
  max: 4,
});

```

###  Full example
HTML
JavaScript

```
<div id="rating-menu"></div>

```


```
// Create the render function
const renderRatingMenu = (renderOptions, isFirstRender) => {
  const { items, refine, createURL, widgetParams } = renderOptions;

  if (isFirstRender) {
    widgetParams.container.appendChild(document.createElement("ul"));

    return;


  widgetParams.container.querySelector("ul").innerHTML = items
    .map(
item) =>
        `<li>

            href="${createURL(item.value)}"
            data-value="${item.value}"
            style="font-weight: ${item.isRefined ? "bold" : ""}"

            ${item.stars.map((isFilled) => (isFilled ? "★" : "☆")).join("")}
            <span>&amp; Up</span>
            <span>${item.count}</span>
          </a>
        </li>`,

    .join("");

  [...widgetParams.container.querySelectorAll("a")].forEach((element) => {
    element.addEventListener("click", (event) => {
      event.preventDefault();
      refine(event.currentTarget.dataset.value);
    });
  });
};

// Create the custom widget
const customRatingMenu = connectRatingMenu(renderRatingMenu);

// Instantiate the custom widget
search.addWidgets([
  customRatingMenu({
    container: document.querySelector("#rating-menu"),
    attribute: "rating",
  }),
]);

```

