##### Replace searchable with a custom implementation
The [`Menu`](https://www.algolia.com/doc/api-reference/widgets/menu/react) widget isn’t searchable. You can create a searchable version by using a custom widget with the [`useRefinementList()`](https://www.algolia.com/doc/api-reference/widgets/refinement-list/react#hook) connector.
React

```
import {
  useRefinementList,
  useInstantSearch,
} from 'react-instantsearch';

function Menu({ attribute, ...props }) {
  const { setIndexUiState } = useInstantSearch();
  const { items, searchForItems, isFromSearch } = useRefinementList({
    attribute,
  });
  const [query, setQuery] = React.useState('');

  function refine(value: string) {
    setQuery('');
    setIndexUiState((uiState) => ({
      ...uiState,
      refinementList: {
        ...uiState.refinementList,
        [attribute]: [value],
      },
    }));


  return (
div {...props}>
input
        type="search"
        value={query}
        onChange={(event) => {
          const nextValue = event.target.value;
          setQuery(nextValue);
          searchForItems(nextValue);

      />
ul>
items.map((item) => (
li key={item.label}>
label>
input
                type="radio"
                checked={item.isRefined}
                onChange={() => refine(item.value)}

isFromSearch ? (
Highlight hit={mapToHit(item)} attribute="highlighted" />
: (
                item.label

            </label>
          </li>
        ))}
      </ul>
    </div>
  );


function mapToHit(item: RefinementListItem): AlgoliaHit<RefinementListItem> {
  return {
    ...item,
    _highlightResult: {
      highlighted: {
        value: item.highlighted,
        matchLevel: 'full',
        matchedWords: [],
      },
    },
    __position: 0,
    objectID: '',
  };


```

