###  Examples
Add analytics tags to product queries
This example adds the tags `autocomplete`, `products`, and `v2` to the search query for products only.
JavaScript

```
document.addEventListener("algolia.hooks.initialize", () => {
	algoliaShopify.hooks.registerHook(
		"beforeAutocompleteConfigurationOptions",
		(config, context) => {
			if (context.sourceId === "products") {
				config.queries = config.queries.map((query) => ({
					...query,
					params: {
						...query.params,
						analyticsTags: ["autocomplete", "products", "v2"],
					},
				}));

			return config;
		},
	);
});

```

Add dynamic filters based on query
This example adds the filter `tags:sale` to the search, if the query includes the word `sale`.
JavaScript

```
document.addEventListener("algolia.hooks.initialize", () => {
	algoliaShopify.hooks.registerHook(
		"beforeAutocompleteConfigurationOptions",
		(config, context) => {
			if (
				context.pluginName === "products" &&
				config.queries[0].query.includes("sale")
			) {
				config.queries = config.queries.map((query) => ({
					...query,
					params: {
						...query.params,
						filters: "tags:sale",
					},
				}));

			return config;
		},
	);
});

```

Add rule contexts to product queries
This example adds custom `ruleContexts` to the product queries in Autocomplete.
JavaScript

```
document.addEventListener("algolia.hooks.initialize", () => {
	algoliaShopify.hooks.registerHook(
		"beforeAutocompleteConfigurationOptions", (config, context) => {
			if (context.sourceId === "products") {
				config.queries = config.queries.map((query) => ({
					...query,
					params: {
						...query.params,
						ruleContexts: ["custom-context", "test-context"],
					},
				}));

			return config;
